package com.adaptivelearning.planning.application;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PlanValidationPolicyTest {private final ZoneId zone=ZoneId.of("Asia/Shanghai");@Test void rejectsLongTask(){LocalDate day=LocalDate.of(2026,7,22);var issues=PlanValidationPolicy.validate(List.of(change("长任务",day,121)),day,day);assertThat(issues).extracting(PlanValidationPolicy.Issue::code).contains("TASK_DURATION_INVALID");}@Test void acceptsValidTask(){LocalDate day=LocalDate.of(2026,7,22);var issues=PlanValidationPolicy.validate(List.of(change("合法任务",day,90)),day,day);assertThat(issues).extracting(PlanValidationPolicy.Issue::code).doesNotContain("TASK_DURATION_INVALID","GOAL_DATE_EXCEEDED","DUPLICATE_TASK");}@Test void rejectsTaskOutsideGoalWindow(){LocalDate day=LocalDate.of(2026,7,22);var issues=PlanValidationPolicy.validate(List.of(change("越界任务",day,60)),day.plusDays(1),day.plusDays(3));assertThat(issues).extracting(PlanValidationPolicy.Issue::code).contains("GOAL_DATE_EXCEEDED");}@Test void rejectsDuplicateTaskSameDay(){LocalDate day=LocalDate.of(2026,7,22);var issues=PlanValidationPolicy.validate(List.of(change("重复任务",day,60),change("重复任务",day,45)),day,day);assertThat(issues).extracting(PlanValidationPolicy.Issue::code).contains("DUPLICATE_TASK");}@Test void canceledTaskSkipsValidation(){LocalDate day=LocalDate.of(2026,7,22);var s=ZonedDateTime.of(day,LocalTime.of(19,0),zone);var cancel=new PlanValidationPolicy.Change("CANCEL_TASK","取消任务",s,s.plusMinutes(300),300,false,true);var issues=PlanValidationPolicy.validate(List.of(cancel),day,day);assertThat(issues).extracting(PlanValidationPolicy.Issue::code).doesNotContain("TASK_DURATION_INVALID");}private PlanValidationPolicy.Change change(String title,LocalDate d,int min){var s=ZonedDateTime.of(d,LocalTime.of(9,0),zone);return new PlanValidationPolicy.Change("ADD_TASK",title,s,s.plusMinutes(min),min,false,true);}}
